import os, re, json

# Load all grids from session log
d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

def parse_grids(text):
    matches = list(re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', text))
    results = {}
    for m in matches:
        k = m[1]
        h, w = int(m[2]), int(m[3])
        rest = text[m.end():].split('\n')[:h]
        if len(rest) == h and all(len(r) == w and all(x.isdigit() for x in r) for r in rest):
            results[k] = [[int(x) for x in r] for r in rest]
    return results

G = parse_grids(t)
print("All keys:", sorted(G.keys()))
for k in sorted(G.keys()):
    print(f"\n{k} ({len(G[k][0])}x{len(G[k])}):")
    for row in G[k]:
        print(' '.join(str(x) for x in row))

